  String t(String key, {Map<String, String>? args}) {
    // Fallback language resolution (e.g. zh_CN -> zh)
    final langValues =
        _localizedValues[languageCode] ??
        _localizedValues[languageCode.split('_').first] ??
        _localizedValues['en'] ??
        {};
    String value = langValues[key] ?? _localizedValues['en']?[key] ?? key;
    if (args != null) {
      args.forEach((k, v) {
        value = value.replaceAll('{$k}', v);
      });
    }
    return value;
  }

  /// Resolves the best matching language code from the user's system locales.
  /// Matches against [supportedLanguages] (including regional handling for Chinese and Norwegian).
  /// If no supported language matches, defaults to English ('en').
  static String resolveSupportedLanguage([List<Locale>? locales]) {
    List<Locale> systemLocales = locales ?? [];
    if (systemLocales.isEmpty) {
      try {
        final dispatcherLocales =
            WidgetsBinding.instance.platformDispatcher.locales;
        if (dispatcherLocales.isNotEmpty) {
          systemLocales = dispatcherLocales;
        } else {
          systemLocales = [WidgetsBinding.instance.platformDispatcher.locale];
        }
      } catch (_) {
        return 'en';
      }
    }

    for (final locale in systemLocales) {
      final lang = locale.languageCode.toLowerCase();
      final script = locale.scriptCode?.toLowerCase();
      final country = locale.countryCode?.toLowerCase();

      // Indonesian legacy code 'in' -> 'id'
      if (lang == 'id' || lang == 'in') {
        return 'id';
      }

      // Chinese variants: zh_CN (Simplified / Hans) vs zh_TW (Traditional / Hant)
      if (lang == 'zh') {
        if (script == 'hant' ||
            country == 'tw' ||
            country == 'hk' ||
            country == 'mo') {
          return 'zh_TW';
        }
        return 'zh_CN';
      }

      // Norwegian mapping: Android/iOS may report 'nb' (Bokmål) or 'nn' (Nynorsk)
      if (lang == 'no' || lang == 'nb' || lang == 'nn') {
        return 'no';
      }

      // Exact match for 2-letter supported codes
      final isSupported = supportedLanguages.any((m) => m['code'] == lang);
      if (isSupported) {
        return lang;
      }
    }

    // Default to English if no supported language is detected
    return 'en';
  }
}
